  async function localFileAction(mode,id,value){const db=await mediaDb();return new Promise((resolve,reject)=>{const tx=db.transaction('files',mode==='get'?'readonly':'readwrite'),store=tx.objectStore('files'),req=mode==='get'?store.get(id):mode==='delete'?store.delete(id):store.put(value,id);req.onsuccess=()=>{if(mode==='get')resolve(req.result);};tx.oncomplete=()=>{db.close();if(mode!=='get')resolve(req.result);};tx.onerror=()=>reject(tx.error);req.onerror=()=>reject(req.error);});}
  const imageItems=()=>mediaLibrary.filter(item=>item&&!item.kind||item?.kind==='gallery');
  const viewableImages=()=>mediaLibrary.filter(item=>item&&(!item.kind||item.kind==='gallery'||item.kind==='cloud-album-image'));
  const mediaSettings=()=>mediaLibrary.find(item=>item?.kind==='settings');
  function syncWorkerUrl(value){let row=mediaSettings();if(!row){row={id:'__oc_media_settings__',kind:'settings'};mediaLibrary.push(row);}row.workerUrl=value;}
  const worldDefaults={a:'#a56e79',b:'#686a9c'};
  function worldColors(timeline){const faction=factions.find(f=>f.id===timeline?.factionId)||factions.find(f=>f.name===timeline?.worldName);const theme=faction?.themeColor;return {a:safeColor(theme?.primary||timeline?.worldColorA||worldDefaults.a),b:safeColor(theme?.secondary||timeline?.worldColorB||worldDefaults.b)};}
  function splitWorldNames(value){return [...new Set(String(value||'').split(/[,，、\n]+/).map(name=>name.trim()).filter(Boolean))];}
  function eventSourceTimeline(event,fallback){return timelines.find(item=>item.id===(event?._sourceTimelineId||fallback?.id))||fallback;}
  function eventWorldName(event,timeline){const source=eventSourceTimeline(event,timeline);return String(event?.worldName||factions.find(f=>f.id===event?.worldFactionId)?.name||source?.worldName||factions.find(f=>f.id===source?.factionId)?.name||'未標記世界觀').trim();}
  const timelineLinkId=link=>link.id||`timeline_${link.timelineId}`;
  const timelineOrderKey=item=>item.kind==='event'?`event:${item.id}`:item.kind==='timeline'?`timeline:${item.id}`:`linkedEvent:${item.timelineId}:${item.eventId}`;
  const linkedEventKey=(timelineId,eventId)=>`${timelineId}::${eventId}`;
