    for(const item of Array.isArray(timeline?.mainTimelineOrder)?timeline.mainTimelineOrder:[]){
      if(item?.kind==='event'&&eventById.has(item.id)&&!seenEvents.has(item.id)){result.push(withTiming({kind:'event',id:item.id},item));seenEvents.add(item.id);}
      else if(item?.kind==='timeline'&&linkById.has(item.id)&&!seenLinks.has(item.id)){result.push(withTiming({kind:'timeline',id:item.id},item));seenLinks.add(item.id);}
      else if(item?.kind==='linkedEvent'){
        const key=linkedEventKey(item.timelineId,item.eventId);
        if(linkedEvents.has(key)&&!seenLinkedEvents.has(key)){result.push(withTiming({kind:'linkedEvent',timelineId:item.timelineId,eventId:item.eventId},item));seenLinkedEvents.add(key);}
      }
    }
    for(const event of own)if(!seenEvents.has(event.id)){result.push({kind:'event',id:event.id});seenEvents.add(event.id);}
