  function openSimultaneousEditor(key){
    const main=timelines.find(item=>item.id===selectedTimelineId&&item.isMainTimeline);if(!main)return;
    const ordered=timelineMainOrder(main),current=ordered.find(item=>timelineOrderKey(item)===key);if(!current)return;
    editingSimultaneousKey=key;
    const names=new Map(timelineEventsForDisplay(main).map(event=>[event._mainOrderKey,`${event.title} · ${event._sourceTimelineName||main.name}`]));
    const select=ensureSimultaneousModal().querySelector('#timelineSimultaneousTarget');
    select.innerHTML='<option value="">不標註同時發生</option>'+ordered.filter(item=>timelineOrderKey(item)!==key).map(item=>`<option value="${esc(timelineOrderKey(item))}">${esc(names.get(timelineOrderKey(item))||'時間線事件')}</option>`).join('');
    const match=ordered.find(item=>timelineOrderKey(item)!==key&&item.simultaneousGroup&&item.simultaneousGroup===current.simultaneousGroup);
    select.value=match?timelineOrderKey(match):'';
    $('timelineSimultaneousLabel').value=current.simultaneousLabel||'';
    $('timelineSimultaneousModal').classList.add('active');
  }
  function saveSimultaneousEditor(){
    const main=timelines.find(item=>item.id===selectedTimelineId&&item.isMainTimeline);if(!main)return;
    const ordered=timelineMainOrder(main),from=ordered.findIndex(item=>timelineOrderKey(item)===editingSimultaneousKey),targetKey=$('timelineSimultaneousTarget').value;
    if(from<0)return;
    const current=ordered[from];
    if(!targetKey){delete current.simultaneousGroup;delete current.simultaneousLabel;}
    else{
      const target=ordered.find(item=>timelineOrderKey(item)===targetKey);if(!target)return;
      const groupId=target.simultaneousGroup||uid('timeline_same_time'),label=$('timelineSimultaneousLabel').value.trim()||target.simultaneousLabel||'同時發生';
      for(const item of ordered)if(item.simultaneousGroup===groupId)item.simultaneousLabel=label;
      target.simultaneousGroup=groupId;target.simultaneousLabel=label;current.simultaneousGroup=groupId;current.simultaneousLabel=label;
      ordered.splice(from,1);
      const last=ordered.findLastIndex(item=>item.simultaneousGroup===groupId);
      ordered.splice(last+1,0,current);
    }
    persistMainTimelineOrder(main,ordered);save();$('timelineSimultaneousModal').classList.remove('active');renderTimeline();
  }
