  function renderTimelineLinks(){const main=timelines.find(item=>item.id===selectedTimelineId),container=$('timelineLinksList');if(!container)return;const links=(main?.linkedTimelines||[]).map(link=>({link,source:timelines.find(item=>item.id===link.timelineId)})).filter(row=>row.source);container.innerHTML=links.length?links.map(({link,source})=>`<article class="timeline-linked-summary"><span class="timeline-linked-icon"><i class="fa-solid fa-link"></i></span><div><strong>${esc(link.mode==='all'?(link.title?.trim()||source.name):source.name)}</strong><small>${link.mode==='all'?`整條時間線 · ${(source.events||[]).length} 個事件 · 即時同步`: `${(link.eventIds||[]).length} 個指定事件 · 即時同步`}${link.mode==='all'&&link.note?` · ${esc(link.note)}`:''}</small></div><button type="button" class="btn btn-xs btn-outline" onclick="OCFeatures.removeTimelineLink('${esc(source.id)}')">解除</button></article>`).join(''):'<p class="timeline-link-empty">尚未關聯其他時間線。</p>';}
