  function openTimelineBookPicker(){const context=timelineBookContext,timeline=timelines.find(row=>row.id===context?.timelineId);if(!timeline)return;let picker=$('timelineBookPickerModal');if(!picker){picker=document.createElement('div');picker.id='timelineBookPickerModal';picker.className='modal-backdrop timeline-book-picker-backdrop';$('timelineBooksModal').after(picker);}const choices=books.filter(book=>!(timeline.linkedBookIds||[]).includes(book.id));picker.innerHTML=`<div class="timeline-book-picker-shell"><header><div><small>WORLD ARCHIVE</small><h3>關聯現有書籍</h3></div><button type="button" class="close-btn" onclick="closeModal('timelineBookPickerModal',true)">×</button></header><div class="timeline-book-picker-list">${choices.length?choices.map(book=>`<button type="button" onclick="OCFeatures.linkTimelineBook('${esc(book.id)}')"><i class="fa-solid fa-book-bookmark"></i><span><strong>${esc(book.title)}</strong><small>${documents.filter(doc=>doc.bookId===book.id).length} 章 · ${esc(book.description||'尚無簡介')}</small></span><i class="fa-solid fa-plus"></i></button>`).join(''):'<p>目前沒有其他可關聯的書籍。</p>'}</div><footer><button type="button" class="btn btn-outline" onclick="closeModal('timelineBookPickerModal',true)">返回書房</button><button type="button" class="btn btn-primary" onclick="closeModal('timelineBookPickerModal',true);OCFeatures.createTimelineBook()">新建書籍</button></footer></div>`;picker.classList.add('active');}
  function linkTimelineBook(id){const timeline=timelines.find(row=>row.id===timelineBookContext?.timelineId),book=books.find(row=>row.id===id);if(!timeline||!book)return;timeline.linkedBookIds=[...new Set([...(timeline.linkedBookIds||[]),id])];timelineBookContext.bookId=id;save();closeModal('timelineBookPickerModal',true);renderTimelineBooks();renderTimeline();}
  function openTimelineChapterEditor(id=null){const context=timelineBookContext;if(!context?.bookId)return;const editor=$('documentModal');$('timelineBooksModal').after(editor);editor.style.zIndex='1040';openDocumentModal(id,context.bookId);}
  function removeTimelineChapter(id){const doc=documents.find(row=>row.id===id&&row.bookId===timelineBookContext?.bookId);if(!doc||!confirm(`將「${doc.title}」移出這本書？章節內容會保留為獨立文檔。`))return;doc.bookId='';save();renderDocumentsModule();renderTimelineBooks();}
  function selectTimelineBook(id){if(!timelineBookContext)return;timelineBookContext.bookId=id;const shell=$('timelineBooksModal')?.querySelector('.timeline-books-shell');if(shell)shell.scrollTop=0;renderTimelineBooks();animateReadingContent($('timelineBooksBody'));}
  function renderTimelineBooks(){
    const context=timelineBookContext,timeline=timelines.find(item=>item.id===context?.timelineId);if(!timeline)return;
    const linked=[...new Set([...(timeline.linkedBookIds||[]),...(context.extraBookIds||[])])].map(id=>books.find(book=>book.id===id)).filter(Boolean),palette=timelineBookPalette(timeline),shell=$('timelineBooksModal'),priorScroll=shell.querySelector('.timeline-books-shell')?.scrollTop||0;
    shell.style.setProperty('--book-a',palette.a);shell.style.setProperty('--book-b',palette.b);shell.style.setProperty('--book-ink',palette.ink);
    $('timelineBooksTitle').textContent=timeline.name;
    $('timelineBooksSubtitle').textContent=linked.length?`${linked.length} 本關聯書籍 · 從世界觀走進故事`:'這條時間線尚未關聯書籍';
    $('timelineBooksTabs').innerHTML=linked.map(book=>`<button type="button" class="${book.id===context.bookId?'is-active':''}" onclick="OCFeatures.selectTimelineBook('${esc(book.id)}')"><i class="fa-solid fa-book-bookmark"></i> ${esc(book.title)}</button>`).join('')+'<button type="button" class="timeline-books-add" onclick="OCFeatures.openTimelineBookPicker()"><i class="fa-solid fa-plus"></i> 關聯書籍</button>';
    const book=linked.find(row=>row.id===context.bookId)||linked[0];if(book)context.bookId=book.id;
    if(!book){$('timelineBooksBody').innerHTML='<div class="timeline-books-empty-state"><i class="fa-solid fa-book-open"></i><h3>書房還是空的</h3><p>建立新書，或關聯已有書籍，就能在此按章閱讀。</p><button type="button" class="btn btn-primary" onclick="OCFeatures.createTimelineBook()">新建並關聯書籍</button><button type="button" class="btn btn-outline" onclick="OCFeatures.openTimelineBookPicker()">關聯現有書籍</button></div>';return;}
    const chapters=documents.filter(doc=>doc.bookId===book.id),people=[...new Set([...(book.charIds||[]),...chapters.flatMap(doc=>doc.charIds||[])])].map(id=>characters.find(char=>char.id===id)).filter(Boolean);
    $('timelineBooksBody').innerHTML=`<div class="timeline-book-intro"><div class="timeline-book-monogram" aria-hidden="true"><i class="fa-solid fa-book-open-reader"></i></div><div><small>THE WORLD ARCHIVE · ${chapters.length} CHAPTERS</small><h3>${esc(book.title)}</h3><p>${esc(book.description||'在章節之間，讀見這個世界。')}</p></div></div>${people.length?`<section class="timeline-book-people"><h4>關聯人物</h4><div>${people.map(char=>`<span class="timeline-book-person" title="${esc(char.name)}"><span class="timeline-book-person-avatar" style="--person-color:${safeColor(char.themeColor?.primary)}">${char.avatar?`<img src="${esc(char.avatar)}" alt="" loading="lazy" onerror="this.remove()">`:esc(char.name.slice(0,1))}</span>${esc(char.name)}</span>`).join('')}</div></section>`:''}<section class="timeline-book-chapters"><div class="timeline-book-chapters-heading"><small>TABLE OF CONTENTS</small><h4>章節目錄</h4></div>${chapters.length?chapters.map((doc,index)=>`<button type="button" class="timeline-book-chapter" onclick="OCFeatures.openTimelineChapter('${esc(doc.id)}')"><span class="timeline-book-chapter-number">${String(index+1).padStart(2,'0')}</span><span class="timeline-book-chapter-copy"><strong>${esc(doc.title)}</strong>${(doc.charIds||[]).length?`<small>登場 · ${esc((doc.charIds||[]).map(id=>characters.find(char=>char.id===id)?.name).filter(Boolean).join('、'))}</small>`:''}</span><i class="fa-solid fa-arrow-up-right-from-square"></i></button>`).join(''):'<p class="timeline-books-empty">這本書還沒有章節。可從時間線設定開啟書籍編輯。</p>'}</section>`;
    shell.querySelector('.timeline-books-shell').scrollTop=priorScroll;
    $('timelineBooksBody').querySelector('.timeline-book-intro')?.insertAdjacentHTML('beforeend','<div class="timeline-book-manage"><button type="button" onclick="OCFeatures.editTimelineBook()"><i class="fa-solid fa-pen"></i> 編輯書籍資料</button></div>');
    $('timelineBooksBody').querySelector('.timeline-book-chapters-heading')?.insertAdjacentHTML('beforeend','<button type="button" class="timeline-book-new-chapter" onclick="OCFeatures.openTimelineChapterEditor()"><i class="fa-solid fa-plus"></i> 新增章節</button>');
    $('timelineBooksBody').querySelectorAll('.timeline-book-chapter').forEach((button,index)=>{const doc=chapters[index],row=document.createElement('div');row.className='timeline-book-chapter-row';button.before(row);row.append(button);row.insertAdjacentHTML('beforeend',`<div class="timeline-book-chapter-actions"><button type="button" onclick="OCFeatures.openTimelineChapterEditor('${esc(doc.id)}')" aria-label="編輯${esc(doc.title)}"><i class="fa-solid fa-pen"></i></button><button type="button" onclick="OCFeatures.removeTimelineChapter('${esc(doc.id)}')" aria-label="將${esc(doc.title)}移出書籍"><i class="fa-solid fa-minus"></i></button></div>`);});
  }
  function openTimelineChapter(id){const context=timelineBookContext,timeline=timelines.find(item=>item.id===context?.timelineId),doc=documents.find(item=>item.id===id);if(!timeline||!doc||doc.bookId!==context.bookId)return;openDocumentReader(id);const palette=timelineBookPalette(timeline),reader=$('documentReaderModal');reader.classList.add('timeline-themed-reader');reader.style.setProperty('--book-a',palette.a);reader.style.setProperty('--book-b',palette.b);reader.style.setProperty('--book-ink',palette.ink);reader.style.setProperty('--book-paper',palette.ink==='#201b25'?`color-mix(in srgb, ${palette.a}, #fffaf4 88%)`:`color-mix(in srgb, ${palette.a}, #18151d 88%)`);reader.style.setProperty('--book-paper-ink',palette.ink==='#201b25'?'#241f27':'#f9f3ee');reader.dataset.timelineBook=context.bookId;let back=$('timelineReaderContentsBtn');if(!back){back=document.createElement('button');back.type='button';back.id='timelineReaderContentsBtn';back.className='btn btn-xs btn-outline';back.innerHTML='<i class="fa-solid fa-list"></i> 章節目錄';back.onclick=()=>closeModal('documentReaderModal',true);reader.querySelector('.doc-reader-actions')?.prepend(back);}back.hidden=false;}
  function openEventBook(bookId,timelineId){if(!books.some(book=>book.id===bookId))return;openTimelineBooks(timelineId,bookId,[bookId]);}
  function openEventDocument(docId,timelineId){const timeline=timelines.find(item=>item.id===timelineId),doc=documents.find(item=>item.id===docId);if(!timeline||!doc)return;if(doc.bookId&&books.some(book=>book.id===doc.bookId)){openTimelineBooks(timelineId,doc.bookId,[doc.bookId]);openTimelineChapter(docId);return;}$('timelineReadModal').after($('documentReaderModal'));openDocumentReader(docId);const palette=timelineBookPalette(timeline),reader=$('documentReaderModal');reader.classList.add('timeline-themed-reader');reader.style.setProperty('--book-a',palette.a);reader.style.setProperty('--book-b',palette.b);reader.style.setProperty('--book-ink',palette.ink);reader.style.setProperty('--book-paper',palette.ink==='#201b25'?'#fffaf4':'#201c24');reader.style.setProperty('--book-paper-ink',palette.ink==='#201b25'?'#241f27':'#f9f3ee');const back=$('timelineReaderContentsBtn');if(back)back.hidden=true;}
  function deleteTimeline(){const item=timelines.find(t=>t.id===selectedTimelineId);if(!item||!confirm(`刪除時間線「${item.name}」及全部事件？`))return;if(timelineReturnContext?.linkedTimelineId===item.id)timelineReturnContext=null;timelines=timelines.filter(t=>t.id!==item.id);for(const timeline of timelines){timeline.linkedTimelines=(timeline.linkedTimelines||[]).filter(link=>link.timelineId!==item.id);if(timeline.isMainTimeline)persistMainTimelineOrder(timeline,timelineMainOrder(timeline));}selectedTimelineId=timelines[0]?.id||'';localStorage.setItem('oc_selected_timeline',selectedTimelineId);save();renderTimeline();}
  function addEventSection(title='',content=''){
    const row=document.createElement('div');row.className='timeline-section-row';
    row.innerHTML=`<input class="timeline-section-title" placeholder="小標題" value="${esc(title)}"><textarea class="timeline-section-content" rows="4" placeholder="撰寫事件詳情…">${esc(content)}</textarea><button type="button" class="btn btn-xs btn-danger" onclick="this.parentElement.remove()">移除段落</button>`;
    $('timelineEventSections').append(row);
  }
  function ensureEventPrimaryFields(){
    if($('timelinePrimaryCharacter'))return;
    const row=document.createElement('div');row.className='timeline-primary-editor';
    row.innerHTML='<div class="timeline-primary-picker"><label for="timelinePrimaryCharacter">主要角色（選填）</label><div class="timeline-primary-search"><div class="timeline-search-field"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><input type="search" id="timelinePrimarySearch" placeholder="搜尋主要角色名稱" aria-label="搜尋主要角色" autocomplete="off"></div><label><input type="checkbox" id="timelinePrimaryRelatedOnly">只看已關聯角色</label></div><select class="themed-select" id="timelinePrimaryCharacter"><option value="">不指定主要角色</option></select><small id="timelinePrimaryCount" aria-live="polite"></small></div><label class="timeline-follow-color"><input type="checkbox" id="timelineAutoCharacterColor" checked><span><strong>使用主要角色的主題色</strong><small>手動調整下方顏色後會改為自訂色彩。</small></span></label>';
    $('timelineEventModal').querySelector('.timeline-colors')?.before(row);
    $('timelinePrimaryCharacter').addEventListener('change',()=>{
      const id=$('timelinePrimaryCharacter').value;
      if(id){const checkbox=[...$('timelineEventChars').querySelectorAll('input[type="checkbox"]')].find(input=>input.value===id);if(checkbox)checkbox.checked=true;}
      updateEventPrimaryColors();
    });
    $('timelinePrimarySearch').addEventListener('input',filterEventPrimaryCharacters);
    $('timelinePrimaryRelatedOnly').addEventListener('change',filterEventPrimaryCharacters);
    $('timelineEventChars').addEventListener('change',filterEventPrimaryCharacters);
    $('timelineAutoCharacterColor').addEventListener('change',updateEventPrimaryColors);
    for(const id of ['timelineColorA','timelineColorB'])$(id).addEventListener('input',()=>{$('timelineAutoCharacterColor').checked=false;});
  }
  function filterEventPrimaryCharacters(){
    const select=$('timelinePrimaryCharacter'),selected=select.value,term=$('timelinePrimarySearch').value.trim().toLocaleLowerCase(),related=new Set([...$('timelineEventChars').querySelectorAll('input:checked')].map(input=>input.value));
    const choices=characters.filter(c=>(!c.isHidden||c.id===selected)&&(!term||c.name.toLocaleLowerCase().includes(term))&&(!$('timelinePrimaryRelatedOnly').checked||related.has(c.id)));
    const current=characters.find(c=>c.id===selected);
    if(current&&!choices.some(c=>c.id===selected))choices.unshift(current);
    select.innerHTML='<option value="">不指定主要角色</option>'+choices.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.name)+(c.id===selected&&term&&!c.name.toLocaleLowerCase().includes(term)?'（目前選定）':'')+'</option>').join('');select.value=selected;
    $('timelinePrimaryCount').textContent=choices.length?'可選 '+choices.length+' 位角色'+(current&&!current.name.toLocaleLowerCase().includes(term)?'（包含目前選定）':''):'沒有符合篩選的角色';
  }
  function updateEventPrimaryColors(){
    if(!$('timelineAutoCharacterColor')?.checked)return;
    const char=characters.find(item=>item.id===$('timelinePrimaryCharacter').value);if(!char)return;
    $('timelineColorA').value=safeColor(char.themeColor?.primary||'#bf806d');
    $('timelineColorB').value=safeColor(char.themeColor?.secondary||char.themeColor?.primary||'#6f629b');
  }
  function ensureEventReadingChoices(){
    if($('timelineEventReadingChoices'))return;
    const panel=document.createElement('section');panel.id='timelineEventReadingChoices';panel.className='timeline-event-reading-choices';
    panel.innerHTML='<div class="timeline-event-reading-title"><i class="fa-solid fa-book-open"></i><div><strong>關聯書籍與章節</strong><small>事件詳情可直接閱讀。每項可單獨決定是否從同人文檔書庫隱藏。</small></div></div><input id="timelineEventReadingSearch" type="search" placeholder="搜尋書籍或章節"><div id="timelineEventReadingList"></div>';
    $('timelineEventSections').closest('.form-group').after(panel);
    $('timelineEventReadingSearch').addEventListener('input',()=>{const term=$('timelineEventReadingSearch').value.trim().toLocaleLowerCase();panel.querySelectorAll('.timeline-event-resource-row').forEach(row=>row.hidden=!!term&&!row.dataset.title.includes(term));});
  }
  function renderEventReadingChoices(event){
    ensureEventReadingChoices();$('timelineEventReadingSearch').value='';
    const row=(item,type,selected)=>`<div class="timeline-event-resource-row" data-title="${esc(String(item.title||'').toLocaleLowerCase())}"><label><input type="checkbox" data-resource-link="${type}" value="${esc(item.id)}" ${selected?'checked':''}><i class="fa-solid ${type==='book'?'fa-book':'fa-file-lines'}"></i><span>${esc(item.title)}</span></label><label class="timeline-event-hide-choice"><input type="checkbox" data-resource-hide="${type}" value="${esc(item.id)}" ${item.hideFromDocuments?'checked':''}><span>書庫隱藏</span></label></div>`;
    $('timelineEventReadingList').innerHTML=`<div class="timeline-event-resource-group"><h4>書籍</h4>${books.map(book=>row(book,'book',(event?.linkedBookIds||[]).includes(book.id))).join('')||'<p>尚無書籍</p>'}</div><div class="timeline-event-resource-group"><h4>章節</h4>${documents.map(doc=>row(doc,'document',(event?.linkedDocumentIds||[]).includes(doc.id))).join('')||'<p>尚無章節</p>'}</div>`;
  }
  function releaseHiddenEventResources(bookIds=[],documentIds=[]){for(const id of bookIds)if(!timelines.some(timeline=>(timeline.linkedBookIds||[]).includes(id)||(timeline.events||[]).some(event=>(event.linkedBookIds||[]).includes(id)))){const book=books.find(row=>row.id===id);if(book)book.hideFromDocuments=false;}for(const id of documentIds)if(!timelines.some(timeline=>(timeline.events||[]).some(event=>(event.linkedDocumentIds||[]).includes(id)))){const doc=documents.find(row=>row.id===id);if(doc)doc.hideFromDocuments=false;}}
  function openEvent(id=null,position=null,sourceTimelineId=selectedTimelineId){
    const timeline=timelines.find(t=>t.id===sourceTimelineId);if(!timeline)return;editingTimelineId=timeline.id;
    const event=(timeline.events||[]).find(item=>item.id===id);
    $('timelineEventModal').dataset.position=position===null?'':String(position);
    $('timelineEventId').value=event?.id||'';
    $('timelineEventTitle').value=event?.title||'';
    $('timelineEventWorld').value=event?.worldName||timelineWorldNames(timeline)[0]||'';
    $('timelineEventWhen').value=event?.when||'';
    $('timelineEventConcurrent').value=event?.simultaneousGroup||'';
    $('timelineEventWorldOptions').innerHTML=knownWorldNames(timeline).map(name=>`<option value="${esc(name)}"></option>`).join('');
    const concurrentOptions=[...new Set((timeline.events||[]).flatMap(row=>[row.when,row.simultaneousGroup]).filter(Boolean))];$('timelineConcurrentOptions').innerHTML=concurrentOptions.map(value=>`<option value="${esc(value)}"></option>`).join('');
    $('timelineEventSummary').value=event?.summary||'';
    $('timelineEventStory').value=event?.story||'';
    $('timelineEventCharSearch').value='';
    $('timelineColorA').value=safeColor(event?.colorA||'#bf806d');
    $('timelineColorB').value=safeColor(event?.colorB||'#6f629b');
    $('timelineEventChars').innerHTML=characters.filter(c=>!c.isHidden||(event?.charIds||[]).includes(c.id)).map(c=>`<label class="checkbox-pill"><input type="checkbox" value="${esc(c.id)}" ${(event?.charIds||[]).includes(c.id)?'checked':''}><span>${esc(c.name)}</span></label>`).join('');
    ensureEventPrimaryFields();
    $('timelinePrimaryCharacter').innerHTML='<option value="">不指定主要角色</option>'+characters.filter(c=>!c.isHidden||c.id===event?.primaryCharId).map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');
    $('timelinePrimaryCharacter').value=event?.primaryCharId||'';
    $('timelinePrimarySearch').value='';$('timelinePrimaryRelatedOnly').checked=false;filterEventPrimaryCharacters();
    $('timelineAutoCharacterColor').checked=event?.colorSource!=='custom';
    updateEventPrimaryColors();
    $('timelineEventSections').replaceChildren();(event?.sections||[]).forEach(section=>addEventSection(section.title,section.content));if(!event)addEventSection();
    renderEventReadingChoices(event);
    $('timelineDeleteEvent').style.display=event?'':'none';$('timelineEventModal').classList.add('active');
  }
  function closeEvent(){ $('timelineEventModal').classList.remove('active');editingTimelineId=''; }
  function saveEvent(){
    const timeline=timelines.find(t=>t.id===editingTimelineId);if(!timeline)return;
    const title=$('timelineEventTitle').value.trim();if(!title)return alert('請輸入事件名稱。');
    timeline.events=timeline.events||[];
    const id=$('timelineEventId').value;let event=timeline.events.find(item=>item.id===id);
    if(!event){event={id:uid('event')};timeline.events.push(event);}
    const previousBookIds=event.linkedBookIds||[],previousDocumentIds=event.linkedDocumentIds||[];
    event.title=title;event.worldName=$('timelineEventWorld').value.trim()||timelineWorldNames(timeline)[0]||'';event.when=$('timelineEventWhen').value.trim();event.simultaneousGroup=$('timelineEventConcurrent').value.trim();event.summary=$('timelineEventSummary').value.trim();event.story=$('timelineEventStory').value.trim();event.colorA=$('timelineColorA').value;event.colorB=$('timelineColorB').value;
    event.charIds=[...$('timelineEventChars').querySelectorAll('input:checked')].map(input=>input.value);
    event.primaryCharId=$('timelinePrimaryCharacter')?.value||'';
    if(event.primaryCharId&&!event.charIds.includes(event.primaryCharId))event.charIds.push(event.primaryCharId);
    event.colorSource=$('timelineAutoCharacterColor')?.checked?'character':'custom';
    if(event.colorSource==='character'&&event.primaryCharId){const char=characters.find(item=>item.id===event.primaryCharId);if(char){event.colorA=safeColor(char.themeColor?.primary||event.colorA);event.colorB=safeColor(char.themeColor?.secondary||char.themeColor?.primary||event.colorB);}}
    event.sections=[...$('timelineEventSections').children].map(row=>({title:row.querySelector('.timeline-section-title').value.trim(),content:row.querySelector('.timeline-section-content').value.trim()})).filter(s=>s.title||s.content);
    event.linkedBookIds=[...$('timelineEventReadingList').querySelectorAll('input[data-resource-link="book"]:checked')].map(input=>input.value);
    event.linkedDocumentIds=[...$('timelineEventReadingList').querySelectorAll('input[data-resource-link="document"]:checked')].map(input=>input.value);
    for(const bookId of event.linkedBookIds){const book=books.find(row=>row.id===bookId),hide=$('timelineEventReadingList').querySelector(`input[data-resource-hide="book"][value="${CSS.escape(bookId)}"]`);if(book&&hide)book.hideFromDocuments=hide.checked;}
    for(const docId of event.linkedDocumentIds){const doc=documents.find(row=>row.id===docId),hide=$('timelineEventReadingList').querySelector(`input[data-resource-hide="document"][value="${CSS.escape(docId)}"]`);if(doc&&hide)doc.hideFromDocuments=hide.checked;}
    releaseHiddenEventResources(previousBookIds.filter(bookId=>!event.linkedBookIds.includes(bookId)),previousDocumentIds.filter(docId=>!event.linkedDocumentIds.includes(docId)));
    if(!id){const rawPos=$('timelineEventModal').dataset.position;const pos=rawPos===''?null:Number(rawPos);if(timeline.isMainTimeline){const ordered=timelineMainOrder(timeline).filter(item=>!(item.kind==='event'&&item.id===event.id)),at=pos===null?ordered.length:Math.max(0,Math.min(Number.isFinite(pos)?pos:ordered.length,ordered.length));ordered.splice(at,0,{kind:'event',id:event.id});persistMainTimelineOrder(timeline,ordered);}else{const ordered=byOrder(timeline.events.filter(item=>item.id!==event.id)),at=pos===null?ordered.length:Math.max(0,Math.min(Number.isFinite(pos)?pos:ordered.length,ordered.length));ordered.splice(at,0,event);ordered.forEach((item,index)=>item.order=index+1);}}
    save();closeEvent();renderTimeline();renderDocumentsModule();
  }
  function deleteEvent(){const timeline=timelines.find(t=>t.id===editingTimelineId),id=$('timelineEventId').value;if(!timeline||!id||!confirm('刪除此事件？'))return;timeline.events=timeline.events.filter(item=>item.id!==id);for(const row of timelines)for(const link of row.linkedTimelines||[])if(link.timelineId===timeline.id&&link.mode==='events')link.eventIds=(link.eventIds||[]).filter(eventId=>eventId!==id);for(const row of timelines)if(row.isMainTimeline)persistMainTimelineOrder(row,timelineMainOrder(row));save();closeEvent();renderTimeline();}
