  async function uploadImages(){const input=$('mediaUploadInput'),files=[...input.files],status=$('mediaUploadStatus');if(!files.length)return;try{for(const file of files){if(!/^image\/(png|jpeg|webp|gif|avif)$/i.test(file.type))throw new Error(`${file.name} 格式不支援，請使用 PNG、JPEG、WebP、GIF 或 AVIF。`);if(file.size>20*1024*1024)throw new Error(`${file.name} 超過 20 MB。`);}for(let i=0;i<files.length;i++){const file=files[i],key=uid('image');status.textContent=`儲存到本機 ${i+1}/${files.length}：${file.name}`;await localFileAction('put',key,file);mediaLibrary.push({id:key,caption:file.name,charIds:[galleryCharId],type:file.type,size:file.size,createdAt:Date.now(),localOnly:true});}save();input.value='';status.textContent=`已加入本機圖庫 ${files.length} 張，可立即預覽；備份人設卡時可批次同步 R2。`;renderGallery();renderCloudAlbumImages();renderCharacterCards();renderCpModule();}catch(error){status.textContent=error.name==='QuotaExceededError'?'本機儲存空間不足，請改用較小圖片或稍後清理瀏覽器資料。':error.message;}}
